  "DisplaySelectionWindow": {
    returnType: "static u8",
    params: "u8 windowType",
    callsTo: ["AddTextPrinterParameterized4","AddWindow","DrawStdFrameWithCustomTileAndPalette","GetFontAttribute","GetMenuCursorDimensionByFont","InitMenuInUpperLeftCorner","ScheduleBgCopyTilemapToVram","SetWindowTemplateFields"],
    lineCount: 33,
    bodyC: "struct WindowTemplate window;\n    u8 cursorDimension;\n    u8 letterSpacing;\n    u8 i;\n\n    switch (windowType)\n    {\n    case SELECTWINDOW_ACTIONS:\n        SetWindowTemplateFields(&window, 2, 19, 19 - (sPartyMenuInternal->numActions * 2), 10, sPartyMenuInternal->numActions * 2, 14, 0x2E9);\n        break;\n    case SELECTWINDOW_ITEM:\n        window = sItemGiveTakeWindowTemplate;\n        break;\n    case SELECTWINDOW_MAIL:\n        window = sMailReadTakeWindowTemplate;\n        break;\n    default:  \n        window = sMoveSelectWindowTemplate;\n        break;\n    }\n\n    sPartyMenuInternal->windowId[0] = AddWindow(&window);\n    DrawStdFrameWithCustomTileAndPalette(sPartyMenuInternal->windowId[0], FALSE, 0x4F, 13);\n    if (windowType == SELECTWINDOW_MOVES)\n        return sPartyMenuInternal->windowId[0];\n    cursorDimension = GetMenuCursorDimensionByFont(FONT_NORMAL, 0);\n    letterSpacing = GetFontAttribute(FONT_NORMAL, FONTATTR_LETTER_SPACING);\n\n    for (i = 0; i < sPartyMenuInternal->numActions; i++)\n    {\n        u8 fontColorsId = (sPartyMenuInternal->actions[i] >= MENU_FIELD_MOVES) ? 4 : 3;\n        AddTextPrinterParameterized4(sPartyMenuInternal->windowId[0], FONT_NORMAL, cursorDimension, (i * 16) + 1, letterSpacing, 0, sFontColorTable[fontColorsId], 0, sCursorOptions[sPartyMenuInternal->actions[i]].text);\n    }\n\n    InitMenuInUpperLeftCorner(sPartyMenuInternal->windowId[0], sPartyMenuInternal->numActions, 0, TRUE);\n    ScheduleBgCopyTilemapToVram(2);\n\n    return sPartyMenuInternal->windowId[0];",
  },
