  "UseSacredAsh": {
    returnType: "static void",
    params: "u8 taskId",
    callsTo: ["AnimatePartySlot","DisplayPartyPokemonLevelCheck","ExecuteTableBasedItemEffect_","GetMonData","PartyMenuModifyHP","PlaySE","ResetHPTaskData","SetPartyMonAilmentGfx"],
    lineCount: 23,
    bodyC: "struct Pokemon *mon = &gPlayerParty[gPartyMenu.slotId];\n    u16 hp;\n\n    if (GetMonData(mon, MON_DATA_SPECIES) == SPECIES_NONE)\n    {\n        gTasks[taskId].func = Task_SacredAshLoop;\n        return;\n    }\n\n    hp = GetMonData(mon, MON_DATA_HP);\n    if (ExecuteTableBasedItemEffect_(gPartyMenu.slotId, gSpecialVar_ItemId, 0))\n    {\n        gTasks[taskId].func = Task_SacredAshLoop;\n        return;\n    }\n\n    PlaySE(SE_USE_ITEM);\n    SetPartyMonAilmentGfx(mon, &sPartyMenuBoxes[gPartyMenu.slotId]);\n    if (gSprites[sPartyMenuBoxes[gPartyMenu.slotId].statusSpriteId].invisible)\n        DisplayPartyPokemonLevelCheck(mon, &sPartyMenuBoxes[gPartyMenu.slotId], 1);\n    AnimatePartySlot(sPartyMenuInternal->tLastSlotUsed, 0);\n    AnimatePartySlot(gPartyMenu.slotId, 1);\n    PartyMenuModifyHP(taskId, gPartyMenu.slotId, 1, GetMonData(mon, MON_DATA_HP) - hp, Task_SacredAshDisplayHPRestored);\n    ResetHPTaskData(taskId, 0, hp);\n    sPartyMenuInternal->tUsedOnSlot = TRUE;\n    sPartyMenuInternal->tHadEffect = TRUE;",
  },
